// The formula guard (v1.0 plan Task 16 Step 1, spec §6): one explain
// trace per registry statistic is generated by the Node wasm build
// (`crates/epiora-wasm/pkg-parity`, built by scripts/check-app.sh)
// straight from the corpus, then every closed-form step's
// `template.compute(step.values)` must reproduce `step.result`
// within the statistic's validation class tolerance (rule E7).
// `method`-kind steps carry inputs and a result only — they are
// described, never re-evaluated (spec §6), so they are skipped.
//
// Tolerance classes come from the validation registry sources
// (`crates/epiora-core/src/validation/registry/*.rs`): each
// `cov("statistic", fixtures, CLASS)` call — including the
// `concat!`-expanded and `stat_entries!`-style rows — is parsed and
// mapped to its `ToleranceClass`.
import { readFileSync, readdirSync } from 'node:fs';
import { createRequire } from 'node:module';
import { resolve } from 'node:path';
import { describe, expect, it } from 'vitest';
import { TEMPLATES } from './index';

// Vitest runs with cwd = app/ — resolve the repo root from it.
const ROOT = resolve(process.cwd(), '..');
const FIXTURES = `${ROOT}/fixtures`;
const REGISTRY_DIR = `${ROOT}/crates/epiora-core/src/validation/registry`;
const PARITY_WASM = `${ROOT}/crates/epiora-wasm/pkg-parity/epiora_wasm.js`;

const CLASS_TOLERANCE: Record<string, number> = {
  ClosedForm: 1e-9,
  Iterative: 1e-6,
};

interface ParityWasm {
  explainCorpusPlan(): [string, string][];
  runCorpusExplainLine(
    fixtureJson: string,
    datasetsJson: string,
    statistic: string,
  ): string;
}

interface TraceStep {
  formula: string;
  values: Record<string, number>;
  result: number | { undefined: string };
}

interface Trace {
  statistic: string;
  kind: 'closed_form' | 'method';
  steps: TraceStep[];
}

function loadParity(): ParityWasm {
  const require = createRequire(import.meta.url);
  return require(PARITY_WASM) as ParityWasm;
}

/** Corpus fixture JSON encodes f64s as 16-hex strings — decode. */
function decode(value: unknown): unknown {
  if (typeof value === 'string' && /^[0-9a-f]{16}$/.test(value)) {
    const buf = Buffer.alloc(8);
    buf.writeBigUInt64BE(BigInt(`0x${value}`));
    return buf.readDoubleBE(0);
  }
  if (Array.isArray(value)) return value.map(decode);
  if (value !== null && typeof value === 'object') {
    const out: Record<string, unknown> = {};
    for (const [k, v] of Object.entries(value)) out[k] = decode(v);
    return out;
  }
  return value;
}

function datasetsJson(): string {
  const datasets: Record<string, unknown> = {};
  for (const f of readdirSync(`${FIXTURES}/data`)) {
    if (!f.endsWith('.dataset.json')) continue;
    const d = JSON.parse(
      readFileSync(`${FIXTURES}/data/${f}`, 'utf8'),
    ) as { id: string };
    datasets[d.id] = d;
  }
  return JSON.stringify(datasets);
}

/** Registry statistic id → tolerance class, parsed from the
 *  validation registry sources (the three `cov` spellings:
 *  direct, `concat!`-expanded macro rows and `stat_entries!`). */
function statisticClasses(): Map<string, string> {
  const classes = new Map<string, string>();
  for (const file of readdirSync(REGISTRY_DIR)) {
    if (!file.endsWith('.rs')) continue;
    const src = readFileSync(`${REGISTRY_DIR}/${file}`, 'utf8');
    // `use ToleranceClass::{ClosedForm as CF, Iterative as IT}` — or
    // the single-alias forms — maps the local token to the variant.
    const alias: Record<string, string> = {};
    for (const m of src.matchAll(
      /ToleranceClass::(?:\{(\w+) as (\w+), (\w+) as (\w+)\}|(\w+)(?: as (\w+))?)/g,
    )) {
      if (m[1] !== undefined) {
        alias[m[2] ?? ''] = m[1];
        alias[m[4] ?? ''] = m[3] ?? '';
      } else {
        alias[m[6] ?? m[5] ?? ''] = m[5] ?? '';
      }
    }
    const classOf = (token: string | undefined): string =>
      (token !== undefined && alias[token]) || token || '';
    for (const m of src.matchAll(
      /cov\(\s*"([^"]+)"\s*,\s*[^,]+?,\s*(?:(\w+)::)?(\w+)\s*,?\s*\)/g,
    )) {
      classes.set(m[1] ?? '', classOf(m[3]));
    }
    const prefixes: string[] = [];
    for (const m of src.matchAll(/(\w+)!\("([^"]+)"\)/g)) {
      if (
        new RegExp(`macro_rules!\\s*${m[1] ?? ''}`).test(src) &&
        m[2] !== undefined
      ) {
        prefixes.push(m[2]);
      }
    }
    for (const m of src.matchAll(
      /cov\(\s*concat!\(\$p, "([^"]+)"\)\s*,\s*[^,]+?,\s*(?:(\w+)::)?(\w+)\s*,?\s*\)/g,
    )) {
      for (const p of prefixes) classes.set(p + (m[1] ?? ''), classOf(m[3]));
    }
    const statEntries = /macro_rules! stat_entries[\s\S]*?cov\(\$id, \$fixtures, ToleranceClass::(\w+)\)/.exec(
      src,
    );
    if (statEntries !== null) {
      for (const m of src.matchAll(/"([^"]+)"\s*=>/g)) {
        classes.set(m[1] ?? '', statEntries[1] ?? '');
      }
    }
  }
  return classes;
}

/** Rule E7 (spec §6.2): |a − e| ≤ tol·|e|, or |a| ≤ tol when e = 0. */
function within(actual: number, expected: number, tol: number): boolean {
  return (
    Math.abs(actual - expected) <= tol * Math.abs(expected) ||
    (expected === 0 && Math.abs(actual) <= tol)
  );
}

describe('formula guard', () => {
  it(
    'substituted_formula_reproduces_value',
    { timeout: 300_000 },
    () => {
      const wasm = loadParity();
      const classes = statisticClasses();
      const datasets = datasetsJson();
      const failures: string[] = [];
      let closed = 0;
      let method = 0;
      for (const [statistic, key] of wasm.explainCorpusPlan()) {
        const fixtureJson = readFileSync(`${FIXTURES}/${key}.json`, 'utf8');
        const line = JSON.parse(
          wasm.runCorpusExplainLine(fixtureJson, datasets, statistic),
        ) as { id: string; explanation: unknown };
        const trace = decode(line.explanation) as Trace;
        const cls = classes.get(line.id);
        const tol = cls !== undefined ? CLASS_TOLERANCE[cls] : undefined;
        if (tol === undefined) {
          failures.push(`${line.id}: no tolerance class in the registry`);
          continue;
        }
        for (const step of trace.steps) {
          const template = TEMPLATES[step.formula];
          if (template === undefined) {
            failures.push(`${line.id}: no template for ${step.formula}`);
            continue;
          }
          if (trace.kind !== 'closed_form') {
            method += 1;
            continue;
          }
          closed += 1;
          if (typeof step.result !== 'number') continue;
          const got = template.compute(step.values);
          if (!within(got, step.result, tol)) {
            failures.push(
              `${line.id}: ${step.formula} → ${got} ≠ ${step.result} ` +
                `(tol ${tol}) values ${JSON.stringify(step.values)}`,
            );
          }
        }
      }
      expect(closed, 'no closed-form traces evaluated').toBeGreaterThan(0);
      expect(method, 'no method traces seen').toBeGreaterThan(0);
      expect(failures).toEqual([]);
    },
  );
});
